import { Block } from "@prototyp/skeletor";
import { NavigationContainerRef } from "modules/navigation/const";
import type { FC } from "react";
import { Image, Pressable, StyleSheet } from "react-native";
import { Colors } from "shared/styles";

const CREATING_CHAT_ROUTES = ["createRoom", "startChat", "invitePeople"];

export const NewChatButton: FC = () => {
  const isCreating = NavigationContainerRef?.isReady()
    ? CREATING_CHAT_ROUTES.includes(
        NavigationContainerRef?.getCurrentRoute()?.name as keyof Routes,
      )
    : false;

  if (isCreating) return null;

  return (
    <Block absolute offsets={{ bottom: 20, right: 20 }} zIndex={2}>
      <Pressable
        style={({ pressed }) =>
          StyleSheet.flatten({
            transform: [{ scale: pressed ? 0.96 : 1 }],
            borderRadius: 40,
            borderWidth: 1,
            width: 60,
            height: 60,
            borderColor: Colors.white10,
            backgroundColor: Colors.primary,
            alignItems: "center",
            justifyContent: "center",
          })
        }
        onPress={() => NavigationContainerRef.navigate("startChat")}
      >
        <Image
          source={require("assets/icons/plus.png")}
          width={24}
          height={24}
        />
      </Pressable>
    </Block>
  );
};

