import { Block, useAnimateParallel } from "@prototyp/skeletor";
import { DebugHelpers } from "modules/matrix-client/helpers";
import type { FC } from "react";
import { useEffect } from "react";
import { Easing, StyleSheet } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { SIDEBAR_WIDTH } from "shared/const";
import { Colors } from "shared/styles";
import {
  Filters,
  Header,
  NewChatButton,
  NoRoomWrapper,
  ProtectAccountMessage,
  Rooms,
  Search,
  SecurityFilter,
} from "../index";
import { useState } from "react";

interface Props {
  currentRoute: string | undefined;
  isVisible: boolean;
}

export const IpadSidebar: FC<Props> = ({ currentRoute, isVisible }) => {
  const [search, setSearch] = useState<string>("");
  const insets = useSafeAreaInsets();

  const transition = useAnimateParallel(
    { translateX: [-SIDEBAR_WIDTH, 0], opacity: [0, 1] },
    { duration: 350, easing: Easing.out(Easing.cubic) },
  );

  useEffect(() => {
    if (!isVisible) return;
    // Delay matches IpadLayoutWrapper's 200ms content-shift delay so both
    // animations start in sync.
    const id = setTimeout(() => {
      // eslint-disable-next-line react-hooks/exhaustive-deps
      transition.start();
    }, 200);
    return () => clearTimeout(id);
  // transition is a stable object from useAnimateParallel; excluding it is
  // intentional to avoid re-running the effect on every render.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isVisible]);

  return (
    <Block
      absolute
      offsets={{ top: 0, left: 0, bottom: 0 }}
      paddings={{ paddingTop: insets.top, paddingBottom: insets.bottom }}
      width={SIDEBAR_WIDTH}
      background={Colors.black}
      border={{
        borderRightWidth: StyleSheet.hairlineWidth,
        borderRightColor: Colors.white10,
      }}
      animations={transition.animations}
    >
      <Header />
      <DebugHelpers />
      <ProtectAccountMessage />
      <NoRoomWrapper>
        <Filters />
        <Search search={search} setSearch={setSearch} />
        <SecurityFilter />
        <NewChatButton currentRoute={currentRoute} />
      </NoRoomWrapper>
      <Rooms search={search} />
    </Block>
  );
};

