      </Button.Wrapper>
      <Button.Wrapper ref={shareButtonRef} style={styles.button} onPress={handleShare}>
        <Block
          width="100%"
          align="center"
          justify="center"
          paddings={12}
          background={Colors.white10}
          border={{ borderRadius: 16 }}
          gap={8}
        >
          <Image
            source={require("assets/icons/upload-simple-large.png")}
            tintColor={Colors.white}
            style={styles.buttonIcon}
            width={24}
            height={24}
          />

          <Text
            size={TextSize.small}
            font="InstrumentSans-Medium"
            color={Colors.white}
          >
            Share
          </Text>
        </Block>
      </Button.Wrapper>
      {canInvite && (
        <Button.Wrapper style={styles.button} onPress={handleInvitePeople}>
          <Block
            width="100%"
            align="center"
            justify="center"
            paddings={12}
            background={Colors.white10}
            border={{ borderRadius: 16 }}
            gap={8}
          >
            <Image
              source={require("assets/icons/user-plus.png")}
              tintColor={Colors.white}
            />

            <Text
              size={TextSize.small}
              font="InstrumentSans-Medium"
              color={Colors.white}
            >
              Invite
            </Text>
          </Block>
        </Button.Wrapper>
