import type {
  RoomInterface,
  RoomMember,
} from "@unomed/react-native-matrix-sdk";
import { useCallback, useState } from "react";

export const useRoomMembers = (room: RoomInterface | undefined) => {
  const [members, setMembers] = useState<RoomMember[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const fetchMembers = useCallback(async () => {
    if (!room) return;
    setIsLoading(true);

    // Step 1: local DB — fast, works offline, shows members immediately
    try {
      const localIterator = await room.membersNoSync();
      const localList = localIterator.nextChunk(10000) ?? [];
      if (localList.length > 0) {
        setMembers(localList);
        setIsLoading(false);
      }
    } catch {}

    // Step 2: server refresh — slower, needs network, ensures up-to-date list
    try {
      const serverIterator = await room.members();
      const serverList = serverIterator.nextChunk(10000) ?? [];
      setMembers(serverList);
    } catch (error) {
      console.error("Failed to fetch members from server:", error);
    } finally {
      setIsLoading(false);
    }
  }, [room]);

  return { members, isLoading, fetchMembers };
};

