59	            rooms.splice(update.inner.index, 0, update.inner.value);
60	            break;
61	          case RoomListEntriesUpdate_Tags.Set:
62	            rooms[update.inner.index] = update.inner.value;
63	            break;
64	          case RoomListEntriesUpdate_Tags.Remove:
65	            rooms.splice(update.inner.index, 1);
66	            break;
67	          case RoomListEntriesUpdate_Tags.PushFront:
68	            rooms.unshift(update.inner.value);
69	            break;
70	          case RoomListEntriesUpdate_Tags.PushBack:
71	            rooms.push(update.inner.value);
72	            break;
73	          case RoomListEntriesUpdate_Tags.PopFront:
74	            rooms.shift();
75	            break;
76	          case RoomListEntriesUpdate_Tags.PopBack:
77	            rooms.pop();
78	            break;
79	          case RoomListEntriesUpdate_Tags.Truncate:
80	            rooms.splice(update.inner.length);
