90	          m !== Membership.Banned &&
91	          m !== Membership.Left &&
92	          m !== Membership.Knocked
93	        );
94	      });
95	
96	      MatrixJotaiStore.set(MatrixAtoms.roomList, filtered);
97	      return filtered;
98	    };
99	
