101	      const addedOrUpdated = updates.flatMap((u) => {
102	        switch (u.tag) {
103	          case RoomListEntriesUpdate_Tags.Reset:
104	            return u.inner.values;
105	          case RoomListEntriesUpdate_Tags.Append:
106	            return u.inner.values;
107	          case RoomListEntriesUpdate_Tags.Insert:
108	            return [u.inner.value];
109	          case RoomListEntriesUpdate_Tags.Set:
110	            return [u.inner.value];
111	          case RoomListEntriesUpdate_Tags.PushFront:
112	            return [u.inner.value];
113	          case RoomListEntriesUpdate_Tags.PushBack:
