164	        stateHandle = roomListService.state({
165	          onUpdate: (state: RoomListServiceState) => {
166	            if (
167	              state === RoomListServiceState.SettingUp ||
168	              state === RoomListServiceState.Recovering
169	            ) {
170	              setIsLoading(true);
171	              if (!hasShownInitialSyncToast.current) {
172	                hasShownInitialSyncToast.current = true;
173	                Toast.show({
174	                  type: "loading",
175	                  text1: "Syncing rooms...",
176	                  autoHide: false,
177	                });
178	              }
179	            }
180	
181	            if (state === RoomListServiceState.Running) {
182	              retryCountRef.current = 0;
183	              // Fallback: refresh from client in case subscription missed any diffs
184	              MatrixCore.refreshRoomList().then(() => {
185	                setIsLoading(false);
186	                Toast.hide();
187	              });
188	            }
189	
190	            if (state === RoomListServiceState.Error) {
191	              if (retryCountRef.current < MAX_SYNC_RETRIES) {
