209	
210	    return () => {
211	      streamHandle?.cancel?.();
212	      stateHandle?.cancel?.();
213	      roomsRef.current = [];
214	      roomListRef.current = null;
215	      entriesResultRef.current = null;
216	    };
217	  }, [client, syncService]);
