import type {
  EventTimelineItem,
  RoomInterface,
  TaskHandleInterface,
  TimelineInterface,
  TimelineItemInterface,
} from "@unomed/react-native-matrix-sdk";
import {
  DateDividerMode,
  ReceiptType,
  TimelineDiff_Tags,
  TimelineFilter,
  TimelineFocus,
  TimelineReadReceiptTracking,
} from "@unomed/react-native-matrix-sdk";
import {
  getItemUniqueKey,
  getTransactionId,
} from "modules/matrix-client/utils";
import { NavigationContainerRef } from "modules/navigation/const";
import { useCallback, useEffect, useRef, useState } from "react";
import { AppState } from "react-native";
import { offlineToastHelper } from "shared/utils";

interface Props {
  room: RoomInterface | undefined;
  roomId: string;
}

const TIMELINE_PAGE_SIZE = 20;
const MIN_INITIAL_EVENTS = 10;
const ENABLE_TIMELINE_DEBUG = __DEV__;

export const useRoomTimeline = ({ room, roomId }: Props) => {
  const [events, setEvents] = useState<EventTimelineItem[]>([]);
  const eventIdsRef = useRef<Set<string>>(new Set());
  const timelineItemsRef = useRef<Array<EventTimelineItem | null>>([]);
  const timelineRef = useRef<TimelineInterface | null>(null);
  const isPaginatingRef = useRef(false);
  const reachedStartRef = useRef(false);
  // const setPinnedEventIds = useSetAtom(TimelineAtoms.pinnedEventIds);
  const [isDirect, setIsDirect] = useState(false);
  /** FIFO queue of transactionIds for in-flight own messages, used to match the final echo Set diff */
  const pendingTransactionIdsQueue = useRef<string[]>([]);
  const rebuildTimerRef = useRef<ReturnType<typeof setTimeout>>(undefined);
  const toEventItem = (item: TimelineItemInterface): EventTimelineItem | null =>
    item.asEvent() ?? null;

  const rebuildEventsFromTimelineItems = useCallback(() => {
    const seenIds = new Set<string>();
    const nextEvents: EventTimelineItem[] = [];

    for (const item of timelineItemsRef.current) {
      if (!item) continue;
      const key = getItemUniqueKey(item);
      if (key) {
        if (seenIds.has(key)) continue;
        seenIds.add(key);
      }
      nextEvents.push(item);
    }

    eventIdsRef.current = seenIds;
    setEvents(nextEvents);
  }, []);

  const markAsRead = useCallback(async () => {
    if (!timelineRef.current) return;
    if (AppState.currentState !== "active") return;

    try {
      // Call markAsRead on the already-initialized timeline, NOT on room.
      // room.markAsRead() internally builds a fresh timeline on every call,
      // which is expensive and throws if no timeline is open yet.
      // See: Element X iOS JoinedRoomProxy.swift — same pattern.
      await timelineRef.current.markAsRead(ReceiptType.Read);
    } catch (error) {
      console.error("Failed to mark room as read:", error);
    }
  }, []);

  const loadMoreMessages = useCallback(async () => {
    if (
      !timelineRef.current ||
      isPaginatingRef.current ||
      reachedStartRef.current
    ) {
      return;
    }

    isPaginatingRef.current = true;

    try {
      const hitStart =
        await timelineRef.current.paginateBackwards(TIMELINE_PAGE_SIZE);
      if (!hitStart) return;
      reachedStartRef.current = true;
    } catch (error) {
      console.error("Failed to load more messages:", error);
    } finally {
      isPaginatingRef.current = false;
    }
  }, []);

  //Hide for now pinned events, because it's not working as expected
  // useEffect(() => {
  //   if (!room) return;
  //   setPinnedEventIds([]);
  //   room
  //     .roomInfo()
  //     .then((info) => {
  //       console.log(info);
  //       setPinnedEventIds(info.pinnedEventIds || []);
  //     })
  //     .catch(console.error);
  //   const handle = room.subscribeToRoomInfoUpdates({
  //     call: (info) => {
  //       console.log(info);
  //       setPinnedEventIds(info.pinnedEventIds || []);
  //     },
  //   });
  //   return () => handle.cancel();
  // }, [room, setPinnedEventIds]);

  useEffect(() => {
    if (!room) return;

    // Reset state when room changes
    setEvents([]);
    timelineItemsRef.current = [];
    eventIdsRef.current.clear();
    pendingTransactionIdsQueue.current = [];

    let timelineListenerHandle: TaskHandleInterface | null = null;
    let isDisposed = false;

    const initRoomTimeline = async () => {
      try {
        const timeline = await room.timelineWithConfiguration({
          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
          filter: new TimelineFilter.All(),
          internalIdPrefix: undefined,
          dateDividerMode: DateDividerMode.Daily,
          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
          reportUtds: false,
        });

        // Store timeline in ref for reuse in pagination
        timelineRef.current = timeline;

        // Set up listener BEFORE paginateBackwards so the SDK's initial
        // cached diffs (from SQLite) are received immediately — no network needed.
        // Set up timeline listener for real-time updates
        timelineListenerHandle = await timeline.addListener({
          onUpdate: (diffs) => {
            const beforeCount = timelineItemsRef.current.length;
            diffs.forEach((diff) => {
              const change = diff.tag;
              const timelineItems = timelineItemsRef.current;
              switch (change) {
                case TimelineDiff_Tags.Append: {
                  if (diff.inner.values.length > 0) {
                    timelineItems.push(...diff.inner.values.map(toEventItem));
                  }
                  break;
                }
                case TimelineDiff_Tags.Insert: {
                  const { index, value } = diff.inner;
                  timelineItems.splice(index, 0, toEventItem(value));
                  break;
                }
                case TimelineDiff_Tags.Set: {
                  const { index, value } = diff.inner;
                  const ev = toEventItem(value);
                  timelineItems[index] = ev;

                  // transactionId -> eventId transition can arrive in an order where
                  // a stale local echo still exists elsewhere in the list.
                  if (
                    ev?.isOwn &&
                    !ev.localSendState &&
                    pendingTransactionIdsQueue.current.length > 0
                  ) {
                    const txId = pendingTransactionIdsQueue.current.shift();
                    if (txId) {
                      const txIndex = timelineItems.findIndex((item) => {
                        if (!item) return false;
                        return getItemUniqueKey(item) === txId;
                      });
                      if (txIndex !== -1) {
                        timelineItems[txIndex] = ev;
                      }
                    }
                  }
                  break;
                }
                case TimelineDiff_Tags.Remove: {
                  const { index: removeIndex } = diff.inner;
                  if (removeIndex >= 0 && removeIndex < timelineItems.length) {
                    timelineItems.splice(removeIndex, 1);
                  }
                  break;
                }
                case TimelineDiff_Tags.PushFront: {
                  const { value } = diff.inner;
                  timelineItems.unshift(toEventItem(value));
                  break;
                }
                case TimelineDiff_Tags.PushBack: {
                  const { value } = diff.inner;
                  const ev = toEventItem(value);
                  timelineItems.push(ev);
                  if (ev) {
                    const txId = getTransactionId(ev);
                    if (txId) {
                      pendingTransactionIdsQueue.current.push(txId);
                    }
                  }
                  break;
                }
                case TimelineDiff_Tags.PopFront: {
                  timelineItems.shift();
                  break;
                }
                case TimelineDiff_Tags.PopBack: {
                  timelineItems.pop();
                  break;
                }
                case TimelineDiff_Tags.Reset: {
                  const resetItems = diff.inner.values;
                  pendingTransactionIdsQueue.current = [];
                  timelineItemsRef.current = resetItems.map(toEventItem);

                  const eventItems = timelineItemsRef.current.filter(
                    (i): i is EventTimelineItem => !!i,
                  );
                  pendingTransactionIdsQueue.current = eventItems
                    .map(getTransactionId)
                    .filter((id): id is string => !!id);
                  break;
                }
                case TimelineDiff_Tags.Truncate: {
                  const { length: cut } = diff.inner;
                  timelineItems.length = cut;
                  break;
                }
                case TimelineDiff_Tags.Clear: {
                  timelineItemsRef.current = [];
                  pendingTransactionIdsQueue.current = [];
                  eventIdsRef.current = new Set();
                  setEvents([]);
                  break;
                }
                default:
                  console.log("Unknown timeline change type:", change);
              }
            });

            if (diffs.some((diff) => diff.tag !== TimelineDiff_Tags.Clear)) {
              if (rebuildTimerRef.current) {
                clearTimeout(rebuildTimerRef.current);
              }
              rebuildTimerRef.current = setTimeout(
                rebuildEventsFromTimelineItems,
                0,
              );
            }

            if (ENABLE_TIMELINE_DEBUG) {
              const afterCount = timelineItemsRef.current.length;
              const tags = diffs.map((d) => d.tag).join(", ");
              console.log(
                `[TimelineDebug][${roomId}] diffs=[${tags}] items ${beforeCount}->${afterCount}`,
              );
            }
          },
        });

        // Mark as read now that the timeline listener is active and the SDK
        // has an open timeline for this room — calling this before
        // timelineWithConfiguration resolves causes the SDK to throw.
        if (!isDisposed) markAsRead().catch(console.error);

        // Paginate after the listener is set up so events flow through it.
        // Loop until we have at least MIN_INITIAL_EVENTS or reach the start.
        isPaginatingRef.current = true;
        (async () => {
          try {
            let hitStart = false;
            while (!isDisposed && !hitStart) {
              hitStart = await timeline.paginateBackwards(TIMELINE_PAGE_SIZE);
              if (hitStart) {
                reachedStartRef.current = true;
                break;
              }
              const eventCount =
                timelineItemsRef.current.filter(Boolean).length;
              if (eventCount >= MIN_INITIAL_EVENTS) break;
            }
          } catch (error) {
            if (!isDisposed) {
              console.warn("Failed to load initial messages:", error);
            }
          } finally {
            isPaginatingRef.current = false;
          }
        })();
      } catch (error) {
        console.error("Failed to initialize room timeline:", error);
        offlineToastHelper("Failed to load the messages. Please try again.");
        NavigationContainerRef.goBack();
        return null;
      }
    };

    initRoomTimeline();

    return () => {
      isDisposed = true;
      timelineListenerHandle?.cancel?.();
      if (rebuildTimerRef.current) clearTimeout(rebuildTimerRef.current);
      timelineRef.current = null;
      timelineItemsRef.current = [];
      isPaginatingRef.current = false;
      reachedStartRef.current = false;
    };
  }, [rebuildEventsFromTimelineItems, room, roomId]);

  useEffect(() => {
    room?.isDirect().then(setIsDirect).catch(console.error);
  }, [room]);

  return {
    events,
    timelineRef,
    isPaginatingRef,
    reachedStartRef,
    isDirect,
    loadMoreMessages,
    markAsRead,
  };
};

import { effectiveWindowWidth } from "shared/utils";

// Functions rather than constants so the value is computed at render time,
// using the settled window dimensions rather than being frozen at module load.
export const getMaxMediaWidth = () => effectiveWindowWidth(true) - 160;
export const getMaxMediaLandscapeWidth = () => effectiveWindowWidth(true) - 80;

import { Dimensions, Platform } from "react-native";
import { SIDEBAR_WIDTH } from "shared/const/sidebar-width";

export const isIpad = (): boolean => Platform.OS === "ios" && Platform.isPad;

export const adaptSize = (phone: number, ipad = phone): number =>
  isIpad() ? ipad : phone;

/** Returns the usable content width for the given context.
 * - Timeline media (isTimeline=true): half the total screen width so images
 *   and videos don't fill the entire right pane on large iPads.
 * - All other content: the full right-pane width (total minus sidebar). */
export const effectiveWindowWidth = (isTimeline?: boolean): number => {
  const { width } = Dimensions.get("window");
  if (isIpad()) return isTimeline ? width / 2 : width - SIDEBAR_WIDTH;
  return width;
};

import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { RoomService } from "modules/room/service/RoomService";
import { useEffect, useState } from "react";
import { ActivityIndicator, Image, Modal, StyleSheet } from "react-native";
import type { Asset } from "react-native-image-picker";
import Toast from "react-native-toast-message";
import { SingleSendItem } from "screens/room/fragments/single-send-item";
import {
  Button,
  GoBackHeader,
  Input,
  IpadScreenWrapper,
  Loading,
  RoomImage,
  ScreenLayout,
} from "shared/components";
import { MAX_MODAL_WIDTH } from "shared/const/max-modal-width";
import { useUploadPhoto } from "shared/hooks";
import { Colors, TextSize } from "shared/styles";
import { isIpad, offlineToastHelper } from "shared/utils";

export const EditRoom: React.FC<NativeStackScreenProps<Routes, "editRoom">> = ({
  route,
}) => {
  const { room } = route.params;
  const {
    isLoading,
    selectedAsset,
    isListOpen,
    handleChoosePhoto,
    handleTakePhoto,
    setIsListOpen,
    setSelectedAsset,
  } = useUploadPhoto();
  const [displayName, setDisplayName] = useState<string | undefined>(
    room?.displayName(),
  );
  const [topic, setTopic] = useState<string | undefined>(room?.topic());
  const [isSaving, setIsSaving] = useState(false);
  const [shouldRemoveAvatar, setShouldRemoveAvatar] = useState(false);
  const [isDirect, setIsDirect] = useState(false);
  const [userPowerLevel, setUserPowerLevel] = useState(0);
  const [nameLevel, setNameLevel] = useState(50);
  const [avatarLevel, setAvatarLevel] = useState(50);
  const [topicLevel, setTopicLevel] = useState(50);
  const canEditName = userPowerLevel >= nameLevel;
  const canEditAvatar = userPowerLevel >= avatarLevel;
  const canEditTopic = userPowerLevel >= topicLevel;

  const isRemoveDisabled = () => {
    if (isSaving || isDirect) return true;

    if (selectedAsset) return false;

    if (room.heroes()[0]?.avatarUrl || room.avatarUrl()) return false;

    return true;
  };

  useEffect(() => {
    room.isDirect().then(setIsDirect).catch(console.error);
    RoomService.getUserPowerLevel(room.id())
      .then((level) => setUserPowerLevel(level ?? 0))
      .catch(console.error);
    RoomService.getRoomPowerLevels(room.id())
      .then((pl) => {
        if (!pl) return;
        const vals = pl.values();
        setNameLevel(Number(vals.roomName));
        setAvatarLevel(Number(vals.roomAvatar));
        setTopicLevel(Number(vals.roomTopic));
      })
      .catch(console.error);
  }, [room]);

  const handleRemove = () => {
    setSelectedAsset(null);
    setShouldRemoveAvatar(true);
  };

  const handleSave = async () => {
    try {
      setIsSaving(true);

      let avatarToUpload: Asset | null | undefined;

      if (shouldRemoveAvatar) {
        avatarToUpload = null; // User wants to remove avatar
      } else if (selectedAsset) avatarToUpload = selectedAsset;

      await RoomService.updateRoom(
        room.id(),
        displayName === room?.displayName() ? undefined : displayName, //if the displayName is the same as the room's displayName, don't update it
        topic === room?.topic() ? undefined : topic, //if the topic is the same as the room's topic, don't update it
        avatarToUpload,
      );

      Toast.show({
        type: "success",
        text1: "Room updated successfully",
      });
    } catch (error) {
      console.error("Failed to update room:", error);
      offlineToastHelper("Failed to update room. Please try again.");
    } finally {
      setIsSaving(false);
    }
  };

  const rightComponent = () => {
    const shouldShow =
      shouldRemoveAvatar ||
      selectedAsset ||
      displayName !== room?.displayName() ||
      topic !== room?.topic();

    if (!shouldShow) return null;

    return (
      <Button.Wrapper onPress={handleSave} disabled={isSaving}>
        <Text>{isSaving ? "Saving..." : "Save"}</Text>
      </Button.Wrapper>
    );
  };

  if (!room) return null;

  return (
    <ScreenLayout>
      {isSaving && <Loading text="Saving..." />}
      <GoBackHeader
        title="Edit Room Details"
        rightComp={rightComponent()}
        margins={{ marginBottom: 40 }}
      />
      <IpadScreenWrapper scrollable>
        <Block align="center">
          <Block margins={{ marginBottom: 8 }}>
            {isLoading ? (
              <Block width={120} height={120} align="center" justify="center">
                <ActivityIndicator />
              </Block>
            ) : selectedAsset?.uri ? (
              <Block
                width={120}
                height={120}
                align="center"
                justify="center"
                border={{ borderRadius: 999 }}
                overflow="hidden"
              >
                <Image
                  source={{ uri: selectedAsset.uri }}
                  width={120}
                  height={120}
                />
              </Block>
            ) : shouldRemoveAvatar ? (
              <Block
                width={120}
                height={120}
                border={{
                  borderRadius: 999,
                  borderWidth: 2,
                  borderColor: Colors.white20,
                }}
                background={Colors.white20}
                align="center"
                justify="center"
              >
                <Text
                  size={TextSize.large}
                  color="white"
                  textTransform="uppercase"
                >
                  {room.displayName()?.charAt(0)}
                </Text>
              </Block>
            ) : (
              <RoomImage
                borderRadius={999}
                room={room}
                width={120}
                height={120}
              />
            )}
          </Block>
          {!isDirect && canEditAvatar && (
            <Block
              flexDirection="row"
              align="center"
              gap={12}
              margins={{ marginBottom: 40 }}
            >
              <Button.Wrapper
                onPress={() => setIsListOpen(true)}
                disabled={isLoading || isSaving}
              >
                <Block
                  flexDirection="row"
                  align="center"
                  gap={12}
                  paddings={[16, 12]}
                >
                  <Image
                    source={require("assets/icons/upload-simple-large.png")}
                    width={16}
                    height={16}
                    style={styles.icon}
                    tintColor={Colors.primary}
                  />
                  <Text size={TextSize.small} color={Colors.primary}>
                    Upload
                  </Text>
                </Block>
              </Button.Wrapper>
              <Button.Wrapper
                onPress={handleRemove}
                disabled={isRemoveDisabled()}
              >
                <Block
                  flexDirection="row"
                  align="center"
                  gap={12}
                  paddings={[16, 12]}
                >
                  <Image
                    source={require("assets/icons/trash.png")}
                    width={16}
                    height={16}
                    style={styles.icon}
                  />
                  <Text size={TextSize.small}>Remove</Text>
                </Block>
              </Button.Wrapper>
            </Block>
          )}
        </Block>
        <Block gap={20}>
          <Block gap={8}>
            <Text
              size={TextSize.tiny}
              color={Colors.white50}
              paddings={[0, 16]}
            >
              Display name
            </Text>
            <Input
              placeholder="Display name"
              value={displayName}
              disabled={isDirect || !canEditName}
              onChangeText={(value) => setDisplayName(value)}
            />
          </Block>
          <Block gap={8}>
            <Text
              size={TextSize.tiny}
              color={Colors.white50}
              paddings={[0, 16]}
            >
              Topic
            </Text>
            <Input
              placeholder="Add a topic"
              value={topic}
              disabled={!canEditTopic}
              onChangeText={(value) => setTopic(value)}
            />
          </Block>
        </Block>
      </IpadScreenWrapper>
      <Modal
        visible={isListOpen}
        transparent={true}
        presentationStyle="overFullScreen"
        animationType="fade"
      >
        <Block
          width="100%"
          height="100%"
          justify={isIpad() ? "center" : "flex-end"}
          align="center"
          background={Colors.black70}
          paddings={[40, 20]}
        >
          {isLoading && <Loading />}
          <Block maxWidth={MAX_MODAL_WIDTH} width="100%" gap={8}>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Chose photo"
                showSeparator
                onPress={handleChoosePhoto}
              />
              <SingleSendItem
                title="Take a photo"
                showSeparator
                onPress={handleTakePhoto}
              />
            </Block>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Cancel"
                onPress={() => setIsListOpen(false)}
              />
            </Block>
          </Block>
        </Block>
      </Modal>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  icon: {
    width: 16,
    height: 16,
  },
});
